mapper.update:
update user_coupon
   set status = 3,
       order_id = #{orderId},
       use_time = null
 where id = #{id}
   and user_id = #{userId}
   and status = 0
   and exists (
       select 1 from coupon c
        where c.id = user_coupon.coupon_id
          and c.status = 1
          and c.start_time <= #{now}
          and c.end_time >= #{now}
   )

update user_coupon
   set status = 1,
       use_time = #{useTime}
 where order_id = #{orderId}
   and status = 3

mapper.select:
select uc.id as user_coupon_id, uc.coupon_id, c.name as coupon_name, c.type, c.full_money, c.minus, c.rate, c.start_time, c.end_time, uc.receive_time, uc.use_time, uc.order_id, case when uc.status = 2 or (uc.status = 0 and c.end_time < #{now}) then 2 else uc.status end as status from user_coupon uc join coupon c on c.id = uc.coupon_id where uc.user_id = #{userId}
and uc.status = 0 and c.end_time >= #{now}
and uc.status = 1
and (uc.status = 2 or (uc.status = 0 and c.end_time < #{now}))
order by uc.id desc
